targets.query:
// Age in seconds. Shared by both streams so the two cannot drift apart.
age = (t) => float(v: int(v: now()) - int(v: t)) / 1000000000.0

air = from(bucket: "sensors")
  |> range(start: -7d)
  |> filter(fn: (r) => r._measurement == "air" and r.device != "sim")
  |> group(columns: ["device", "_field"])
  |> last()
  |> map(fn: (r) => ({ device: r.device, _field: r._field, _value: age(t: r._time) }))

// The AS7341 publishes to its own measurement, so a query that stopped at `air`
// could never show it. That is not hypothetical: on 2026-08-14 and again on
// 08-16 the spectrum feed went silent for 32 minutes while every cell in this
// table stayed green. A dropped sensor showing as green is the one outcome this
// panel exists to prevent.
//
// `mode` is load-bearing. A reflectance run writes to the SAME measurement as
// mode "reflect" and holds the sensor while it goes, so counting those samples
// would let an active bench session hide a dead ambient feed.
//
// One column rather than ten: the channels are a single JSON publish, they
// arrive together or not at all, so `clear` stands in for all of them.
spectrum = from(bucket: "sensors")
  |> range(start: -7d)
  |> filter(fn: (r) => r._measurement == "spectrum" and r.mode == "ambient"
       and r._field == "clear" and r.device != "sim")
  |> group(columns: ["device"])
  |> last()
  |> map(fn: (r) => ({ device: r.device, _field: "as7341", _value: age(t: r._time) }))

union(tables: [air, spectrum])
  |> group()
  |> keep(columns: ["device", "_field", "_value"])
  |> pivot(rowKey: ["device"], columnKey: ["_field"], valueColumn: "_value")

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  // a pot cannot weigh <= 0 — those are tare drift with nothing on the scale
  |> filter(fn: (r) => r._value > 0.0)
  // "unknown" is not a plant: it is every unregistered tag pooled into one
  // bucket, so a trend line through it would average unrelated objects.
  // The table below lists them so the missing registrations stay visible.
  // Same soft-delete filter as the daily dashboard. Without it a reading retired
  // with mark-weight.sh stays visible here, so the two dashboards disagree about
  // what the data is — the worst outcome for a marker whose whole point is that
  // one decision applies everywhere.
  |> filter(fn: (r) => r.quality == "ok" and r.plant_id != "unknown")
  |> group(columns: ["plant_id"])
  // One value per plant per LOCAL day. Weighing is a manual, bursty act —
  // several taps within a session are the same measurement repeated, so the
  // median gives the day's figure and discards a fumbled weigh.
  |> aggregateWindow(every: 1d, fn: median, createEmpty: false)
  |> keep(columns: ["_time", "_value", "plant_id"])
  |> yield(name: "weight")
